10	 *   (a) subcontagem — bips concorrentes do mesmo item liam a mesma base e
11	 *       sobrescreviam (2 bips → quantidade_enviada "1");
12	 *   (b) bip que não preenche — item casado por `masterId` ausente no front
13	 *       caía em "não encontrado" e era engolido (fica 0/N, re-bip = "já lido").
14	 */
15	import { calcularIncrementoBip } from '@/shared/hooks/useEtiquetaScanner';
16	
17	export interface BipMatchItem {
18	  id: number;
19	  produto_nome: string;
20	  masterId?: number;
21	  quantidade_enviada?: string | number | null;
22	  unidade_medida?: string | null;
23	  selectedBatches?: Record<string, number>;
24	}
