70	 * abertura do modal a partir de `quantidade_enviada`. A base sai SEMPRE do
71	 * acumulador quando presente; só cai em `quantidade_enviada` se o item ainda
72	 * não foi seedado (defensivo). Não muta `accum` — o caller grava após o onApply.
73	 *
74	 * Incremento universal (via calcularIncrementoBip):
75	 *   tipo da etiqueta é container (caixa/saco/pote/…) → +1
76	 *   senão (granel/un/kg)                              → +quantidade_interna
77	 */
78	export function computeNovaQtd(
79	  accum: Map<number, number>,
80	  item: BipMatchItem,
81	  tipoEmbalagemEtiqueta: string | null | undefined,
82	  qtyInternaEtiqueta: number,
83	): { base: number; incremento: number; nova: number } {
