98	 * independente da unidade do pedido, pra o estoque por lote ficar correto.
99	 */
100	export function accumBatches(
101	  current: Record<string, number> | undefined,
102	  loteId: string | null | undefined,
103	  qtyFisica: number,
104	): Record<string, number> {
105	  const next: Record<string, number> = { ...(current || {}) };
106	  if (loteId) next[loteId] = (next[loteId] || 0) + (Number(qtyFisica) || 0);
107	  return next;
108	}
