              selectedBatches: batches || i.selectedBatches,
              lote: loteString || i.lote,
            }
          : i,
      ),
    );

    setPendingSent((prev) => ({ ...prev, [itemId]: enviada }));

    // Update DB
    const updatePayload: any = { quantidade_enviada: enviada };
    if (batches) {
      updatePayload.lote = loteString;
    }

    await supabase
